import{_ as t,o,c as s,a3 as a}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"Tenancy, Identity & Access","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/tenancy-and-identity.md","filePath":"concepts/tenancy-and-identity.md"}'),d={name:"concepts/tenancy-and-identity.md"};function r(n,e,c,i,h,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="tenancy-identity-access" tabindex="-1">Tenancy, Identity &amp; Access <a class="header-anchor" href="#tenancy-identity-access" aria-label="Permalink to &quot;Tenancy, Identity &amp; Access&quot;">​</a></h1><p>Saidi runs one codebase for a laptop install and a hosted workspace. The seam that makes that possible is a <strong>tenant context</strong>: a small record saying <em>who</em> is acting inside <em>which</em> organization, carried implicitly through every call. Store lookups, filesystem paths, budgets, and permission checks all read that one record.</p><p>This page is the architecture behind the reference tables in <a href="/docs/reference/orgs-auth-permissions">Orgs, Auth &amp; Permissions</a> — read that page for the operator-facing summary.</p><h2 id="the-tenant-context" tabindex="-1">The tenant context <a class="header-anchor" href="#the-tenant-context" aria-label="Permalink to &quot;The tenant context&quot;">​</a></h2><p><code>TenantContext</code> is the whole principal. It lives in an <code>AsyncLocalStorage</code> scope, so it follows <code>await</code> boundaries without being threaded through every signature.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>orgId</code></td><td>The acting workspace. Every store read and every path is scoped by it</td></tr><tr><td><code>userId</code></td><td>The acting member. <code>&#39;local&#39;</code> or <code>&#39;system&#39;</code> for non-human scopes</td></tr><tr><td><code>role</code></td><td><code>owner</code> | <code>admin</code> | <code>member</code> — the org role</td></tr><tr><td><code>platformRole</code></td><td><code>user</code> | <code>superadmin</code> — the platform (host) role, separate from org role</td></tr><tr><td><code>userName</code> / <code>userEmail</code></td><td>Display identity, set only where the <code>User</code> record is already loaded</td></tr><tr><td><code>via</code></td><td>How the scope entered: <code>ui</code>, <code>ws</code>, <code>cron</code>, <code>reflex</code>, <code>telegram</code>, <code>run</code>, <code>system</code></td></tr></tbody></table><p>Two accessors read it:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// throws in cloud mode if no scope was opened</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tenantOrNull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// never throws; null when no scope is open</span></span></code></pre></div><p>The asymmetry is deliberate. A missing scope is a bug in an entry point, not a condition to paper over — so <code>tenant()</code> throws loudly rather than silently defaulting to some other org&#39;s data.</p><h2 id="per-org-stores-and-paths" tabindex="-1">Per-org stores and paths <a class="header-anchor" href="#per-org-stores-and-paths" aria-label="Permalink to &quot;Per-org stores and paths&quot;">​</a></h2><p>Each org gets its own set of the <em>existing</em> store classes — runs, crons, chats, reflexes, credits, playbooks — constructed with org-scoped persistence. The module singletons other code imports (<code>runs</code>, <code>chats</code>, …) are <code>ambient()</code> proxies: every property access resolves the current tenant&#39;s instance and forwards to it, so <code>runs.list()</code> at a call site is unchanged while returning a different set per org.</p><p>Each workspace&#39;s state nests one level under the platform data root:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orgs/&lt;orgId&gt;/</span></span>
<span class="line"><span>├── memory/   runs (incl. work/ and assets/), project + agent memory, global.md</span></span>
<span class="line"><span>├── agents/   AGENT.md dirs, skills, mcp.json</span></span>
<span class="line"><span>├── config/   org-visible config</span></span>
<span class="line"><span>└── repos/    server-side project clones</span></span></code></pre></div><p><code>safeOrgId()</code> rejects anything that isn&#39;t <code>[A-Za-z0-9][A-Za-z0-9_-]{0,63}</code> before an id is ever joined into a path, so a crafted org id cannot escape its own workspace root.</p><p>Structured records are filtered rather than pathed: the run persistence layer holds an optional <code>orgId</code> and folds <code>{ orgId }</code> into every query. <code>ensureOrgStores()</code> hydrates an org&#39;s stores from Mongo exactly once and is awaited by every entry point before serving, so the synchronous store reads that follow see durable data.</p><p>Genuinely global files stay global: <code>settings.json</code>, <code>secrets.json</code>, and the legacy <code>telegram.json</code> deliberately use the module-level constants, not the org-scoped helpers.</p><h2 id="who-opens-a-scope" tabindex="-1">Who opens a scope <a class="header-anchor" href="#who-opens-a-scope" aria-label="Permalink to &quot;Who opens a scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry point</th><th>Scope source</th><th><code>via</code></th></tr></thead><tbody><tr><td>HTTP request</td><td><code>orgContext</code> middleware — <code>X-Saidi-Org</code> header → membership</td><td><code>ui</code></td></tr><tr><td>WebSocket</td><td>Upgrade handler — cookie session + <code>?org=</code> query param</td><td><code>ws</code></td></tr><tr><td>Run turn / delegation</td><td><code>tenantForRun(run)</code> — the run&#39;s <code>orgId</code> + <code>createdBy</code></td><td><code>run</code></td></tr><tr><td>Cron fire</td><td><code>tenantForCron(job)</code> — the job&#39;s <code>orgId</code> + <code>createdBy</code></td><td><code>cron</code></td></tr><tr><td>Reflex fire</td><td><code>tenantForReflex(reflex)</code></td><td><code>reflex</code></td></tr><tr><td>Boot / schedulers</td><td><code>systemTenant(orgId)</code> — <code>userId: &#39;system&#39;</code></td><td><code>system</code></td></tr></tbody></table><p>Automations act <strong>as their creator</strong>, never as an anonymous org actor. A cron&#39;s fired run resolves the creator&#39;s budget, effort ceiling, and agent access; a run&#39;s every turn resolves against <code>createdBy</code> regardless of who enqueued the work. See <a href="/docs/concepts/runs">Runs</a> for how that interacts with sharing.</p><h2 id="authenticating-a-request" tabindex="-1">Authenticating a request <a class="header-anchor" href="#authenticating-a-request" aria-label="Permalink to &quot;Authenticating a request&quot;">​</a></h2><p>Cloud mode mounts four middlewares in order:</p><ol><li><strong><code>csrfOriginCheck</code></strong> — for <code>POST</code>/<code>PUT</code>/<code>PATCH</code>/<code>DELETE</code>, rejects a request whose <code>Sec-Fetch-Site</code> is cross-site, or whose <code>Origin</code> host matches neither the inbound <code>Host</code> nor the operator-declared <code>SAIDI_PUBLIC_URL</code> host (needed because a proxy rewrites <code>Host</code>). Defense in depth on top of the cookie&#39;s <code>SameSite=Lax</code>.</li><li><strong><code>requireSession</code></strong> — reads the <code>saidi_session</code> cookie, validates it, and stashes <code>{ user, session }</code>; 401 otherwise.</li><li><strong><code>orgContext</code></strong> — reads <code>X-Saidi-Org</code>, verifies membership, loads the org and its stores, resolves the permission set, and opens the tenant scope that the rest of the handler chain runs inside.</li><li><strong><code>requirePermission(key)</code> / <code>requireOwner</code> / <code>requireSuperadmin</code></strong> — per-route gates mounted after the context resolver.</li></ol><p><code>orgContext</code> has two branches worth knowing: a <strong>suspended</strong> org still serves <code>GET</code> but returns <code>403 org_suspended</code> on any mutation, and a <strong>platform superadmin</strong> who is not a member gets a virtual owner-level membership so they can open the workspace to inspect it — nothing is persisted for that spectate membership.</p><p>The WebSocket upgrade repeats the same checks at handshake time: an Origin allowlist (<code>verifyClient</code>), the session cookie, the <code>?org=</code> membership check, and the same superadmin carve-out. It also tags the socket with <code>runs.viewAll</code> / <code>chats.viewAll</code> so broadcast frames can be scoped per socket rather than filtered per client.</p><h2 id="sessions-and-tokens-as-implemented" tabindex="-1">Sessions and tokens as implemented <a class="header-anchor" href="#sessions-and-tokens-as-implemented" aria-label="Permalink to &quot;Sessions and tokens as implemented&quot;">​</a></h2><p>Every token in the auth stack is an opaque 32-byte random string rendered base64url. <strong>Only <code>sha256(token)</code> is stored</strong> — a database leak cannot yield a live session, password-reset link, or invite link.</p><table tabindex="0"><thead><tr><th>Token</th><th>Lifetime</th><th>Notes</th></tr></thead><tbody><tr><td>Session</td><td>30 days sliding, 90 days absolute</td><td>Renewed at most once an hour, to avoid a write per request</td></tr><tr><td><code>verify_email</code></td><td>24 hours</td><td>One-shot; consumed by an atomic <code>findOneAndUpdate</code></td></tr><tr><td><code>reset_password</code></td><td>1 hour</td><td>Same one-shot consumption</td></tr><tr><td>Invite</td><td>7 days</td><td>Bound to an email address; re-issuing invalidates the old link</td></tr><tr><td>OAuth <code>state</code></td><td>10 minutes</td><td>In-process, single-use</td></tr></tbody></table><p>The session cookie is <code>saidi_session</code>, set <code>HttpOnly</code>, <code>SameSite=Lax</code>, <code>Path=/</code>, with <code>Secure</code> added when the request arrived over HTTPS (directly or via a proxy setting <code>X-Forwarded-Proto</code>). Validation deletes an expired session, refuses a disabled user, and slides the expiry — capped at the absolute deadline. <code>revokeAllSessions(userId)</code> exists for password reset, disable, and removal.</p><p>Passwords use scrypt (<code>N=16384, r=8, p=1</code>, 32-byte key) with a minimum length of 10, stored self-describing as <code>scrypt$N$r$p$salt$hash</code> so cost parameters can be raised — or the algorithm swapped — without invalidating existing hashes.</p><p>Google and GitHub OAuth are an authorization-code redirect flow configured entirely by platform environment variables (<code>SAIDI_GOOGLE_CLIENT_ID</code>/<code>_SECRET</code>, <code>SAIDI_GITHUB_CLIENT_ID</code>/<code>_SECRET</code>, with <code>SAIDI_PUBLIC_URL</code> as the redirect base) — see <a href="/docs/reference/settings">Settings</a>. The login screen offers only the providers whose id <em>and</em> secret are set. The <code>state</code> is bound to the initiating browser by a short-lived <code>saidi_oauth_state</code> cookie carrying <code>sha256(state)</code>, so a state minted in an attacker&#39;s browser cannot be replayed into a victim&#39;s. GitHub&#39;s profile email is often private, so the flow reads <code>/user/emails</code> to get a <em>verified</em> address before auto-linking.</p><p>The first account whose email matches <code>SAIDI_SUPERADMIN_EMAIL</code> becomes the platform superadmin, idempotently, on signup or login.</p><h2 id="secrets-at-rest" tabindex="-1">Secrets at rest <a class="header-anchor" href="#secrets-at-rest" aria-label="Permalink to &quot;Secrets at rest&quot;">​</a></h2><p>Tenant secrets — org webhook secrets, channel bot tokens, user connection tokens — use envelope encryption: AES-256-GCM under a random per-record data key, itself wrapped by a deployment master key from <code>SAIDI_MASTER_KEY</code>. Rotating the master key re-wraps the (tiny) data keys instead of re-encrypting payloads, and per-record keys bound the blast radius of any one disclosure.</p><p><code>SAIDI_MASTER_KEY</code> accepts 64 hex characters or base64 for exactly 32 bytes; any other non-empty value is treated as a passphrase and stretched with scrypt so a low-entropy operator passphrase is not offline-brute-forceable against a captured blob. The platform refuses to boot without it, so a stored secret is never at rest in plaintext.</p><h2 id="roles-and-permissions-in-code" tabindex="-1">Roles and permissions in code <a class="header-anchor" href="#roles-and-permissions-in-code" aria-label="Permalink to &quot;Roles and permissions in code&quot;">​</a></h2><p>The permission catalog is a versioned constant, not a database table — adding a key is a code change with no migration. A membership stores only <em>sparse overrides</em>, which <code>resolvePermissions(role, overrides)</code> merges over the role defaults.</p><table tabindex="0"><thead><tr><th>Key</th><th>Owner</th><th>Admin</th><th>Member</th></tr></thead><tbody><tr><td><code>runs.create</code>, <code>runs.approve</code></td><td>✔</td><td>✔</td><td>✔</td></tr><tr><td><code>runs.viewAll</code>, <code>runs.steerAll</code>, <code>runs.approveAll</code></td><td>✔</td><td>✔</td><td>—</td></tr><tr><td><code>chats.viewAll</code></td><td>✔</td><td>✔</td><td>—</td></tr><tr><td><code>agents.manage</code>, <code>crons.manage</code>, <code>reflexes.manage</code>, <code>memory.manage</code></td><td>✔</td><td>✔</td><td>—</td></tr><tr><td><code>usage.viewOrg</code>, <code>billing.view</code>, <code>members.manage</code></td><td>✔</td><td>✔</td><td>—</td></tr><tr><td><code>settings.manage</code></td><td>✔</td><td>—</td><td>—</td></tr><tr><td><code>market.install.skill</code> / <code>.mcp</code> / <code>.agent</code> / <code>.department</code>, <code>market.publish</code></td><td>✔</td><td>✔</td><td>—</td></tr></tbody></table><p>There are deliberately no custom roles and no permission groups; both can layer on later without a schema change. Client-supplied overrides pass through <code>sanitizeOverrides()</code>, which keeps only known keys with boolean values.</p><p>Agent access is separate from permissions: <code>AgentAccess</code> is <code>{ mode: &#39;all&#39; | &#39;allowlist&#39; | &#39;denylist&#39;, agents }</code>, and <code>canUseAgent(access, name)</code> is the gate PRIME&#39;s delegation consults before routing work to an agent.</p><h2 id="where-the-checks-actually-run" tabindex="-1">Where the checks actually run <a class="header-anchor" href="#where-the-checks-actually-run" aria-label="Permalink to &quot;Where the checks actually run&quot;">​</a></h2><p>Permission checks happen at three layers, and they answer different questions:</p><ul><li><strong>Route gates</strong> — <code>requirePermission(key)</code> returns <code>403 permission_denied:&lt;key&gt;</code> before a handler runs. Coarse, per-endpoint.</li><li><strong>Per-object ACLs</strong> — <code>canViewRun</code> / <code>canSteerRun</code> combine ownership (<code>createdBy</code>), the <code>sharedWith</code> list, and the spectator flag. Every route that reads or mutates a run&#39;s data, git views, files, or assets goes through them.</li><li><strong>Delivery scoping</strong> — <code>scopeStateForUser()</code> narrows the org-wide state snapshot at the point of delivery: runs filtered to own-plus-shared, chats likewise, agents and departments filtered to the member&#39;s allowlist, and the recent-activity feed restricted to chats the viewer can see so another member&#39;s transcript never rides along in the payload.</li></ul><p>Budget enforcement sits in front of dispatch and reads the same ambient context, with memberships and orgs cached for ~30 seconds because it runs on every delegation. Per-member ceilings (<code>MemberLimits</code>) cover monthly credit budget, a one-time extra grant, a per-run cost cap that <em>pauses</em> rather than cancels, an effort ceiling that <em>clamps</em> rather than rejects, and a concurrent-run limit. <code>0</code> or <code>&#39;&#39;</code> means &quot;no member-level limit&quot;.</p><h2 id="the-channel-caveat" tabindex="-1">The channel caveat <a class="header-anchor" href="#the-channel-caveat" aria-label="Permalink to &quot;The channel caveat&quot;">​</a></h2><p>Chat channels are the one surface not yet wired into this model. <code>startChannels()</code> is called only when <code>!isCloud()</code>, and the Telegram inbound path authorizes against a flat global allow-list of Telegram user ids rather than resolving a per-member channel identity. The channel-identity registry exists but is not yet called by any adapter or route. Treat channel access as &quot;this install&#39;s owner&quot;, not as per-member auth — see <a href="/docs/guides/telegram">Connecting Telegram</a> for what that means in practice.</p>`,45)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
